class AppError(Exception):
    code = 500


class ValidationError(AppError):
    code = 400


class AuthError(AppError):
    code = 401


class UserStore:
    def __init__(self):
        self.users = {}

    def register(self, user, pwd):
        if len(pwd) < 6:
            raise ValidationError("password too short")
        if user in self.users:
            raise ValidationError("user exists")
        self.users[user] = pwd

    def login(self, user, pwd):
        if self.users.get(user) != pwd:
            raise AuthError("invalid credentials")


store = UserStore()

q = int(input())
for _ in range(q):
    command, user, pwd = input().split()
    try:
        if command == "REGISTER":
            store.register(user, pwd)
            print(f"REGISTERED {user}")
        elif command == "LOGIN":
            store.login(user, pwd)
            print(f"WELCOME {user}")
    except AppError as e:               # catches every subclass too
        print(f"{type(e).__name__}[{e.code}]: {e}")

class Vehicle:
    wheels = 0

    def __init__(self, make, model, year):
        self.make = make
        self.model = model
        self.year = year

    def describe(self):
        return f"{self.year} {self.make} {self.model}"


class Car(Vehicle):
    wheels = 4

    def __init__(self, make, model, year, doors):
        super().__init__(make, model, year)
        self.doors = doors

    def describe(self):
        return super().describe() + f" ({self.doors} doors)"


class ElectricCar(Car):
    def __init__(self, make, model, year, doors, kwh):
        super().__init__(make, model, year, doors)
        self.kwh = kwh

    def describe(self):
        return super().describe() + f" [{self.kwh} kWh]"


