class Employee:
    def __init__(self, name):
        self.name = name

    def monthly_pay(self):
        raise NotImplementedError


class Salaried(Employee):
    def __init__(self, name, annual):
        super().__init__(name)
        self.annual = annual

    def monthly_pay(self):
        return self.annual / 12


class Hourly(Employee):
    def __init__(self, name, rate, hours):
        super().__init__(name)
        self.rate = rate
        self.hours = hours

    def monthly_pay(self):
        normal = min(self.hours, 160)
        overtime = max(0, self.hours - 160)
        return self.rate * normal + 1.5 * self.rate * overtime


staff = []

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "SALARIED":
        staff.append(Salaried(parts[1], float(parts[2])))
    elif parts[0] == "HOURLY":
        staff.append(Hourly(parts[1], float(parts[2]), float(parts[3])))
    elif parts[0] == "PAYROLL":
        total = 0
        for e in staff:
            pay = e.monthly_pay()       # polymorphic call
            total += pay
            print(f"{e.name} ({type(e).__name__}): {pay:.2f}")
        print(f"TOTAL: {total:.2f}")

from abc import ABC, abstractmethod


class PaymentGateway(ABC):
    @abstractmethod
    def fee(self, amount):
        pass

    def pay(self, amount):
        fee = self.fee(amount)
        return amount + fee, fee


class CreditCard(PaymentGateway):
    def fee(self, amount):
        return amount * 0.029 + 0.30


class UPI(PaymentGateway):
    def fee(self, amount):
        return 0.0


class Crypto(PaymentGateway):
    def fee(self, amount):
        return 1.00 + amount * 0.01


gateways = {"CARD": CreditCard(), "UPI": UPI(), "CRYPTO": Crypto()}

q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "ABSTRACT":
        try:
            PaymentGateway()
        except TypeError:
            print("CANNOT INSTANTIATE PaymentGateway")
    elif parts[0] == "PAY":
        method, amount = parts[1], float(parts[2])
        if method not in gateways:
            print("UNKNOWN METHOD")
        elif amount <= 0:
            print("INVALID AMOUNT")
        else:
            gateway = gateways[method]
            total, fee = gateway.pay(amount)
            print(f"{type(gateway).__name__}: charged {total:.2f} (fee {fee:.2f})")

import math


class Shape:
    def area(self):
        raise NotImplementedError


class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return math.pi * self.r * self.r


class Polygon(Shape):
    def __init__(self, points):
        if len(points) < 3:
            raise ValueError("polygon needs at least 3 points")
        self.points = points

    def area(self):
        n = len(self.points)
        total = 0
        for i in range(n):
            x1, y1 = self.points[i]
            x2, y2 = self.points[(i + 1) % n]
            total += x1 * y2 - x2 * y1
        return abs(total) / 2


shapes = []

q = int(input())
for _ in range(q):
    parts = input().split()
    command = parts[0]
    if command == "CIRCLE":
        shapes.append(Circle(float(parts[1])))
    elif command == "POLYGON":
        nums = [float(p) for p in parts[1:]]
        try:
            shapes.append(Polygon(list(zip(nums[0::2], nums[1::2]))))
        except ValueError as e:
            print(f"INVALID: {e}")
    elif command == "LIST":
        for s in shapes:
            print(f"{type(s).__name__}: {s.area():.2f}")
    elif command == "TOTAL":
        print(f"{sum(s.area() for s in shapes):.2f}")
    elif command == "LARGEST":
        if shapes:
            big = max(shapes, key=lambda s: s.area())
            print(f"{type(big).__name__}: {big.area():.2f}")
        else:
            print("NONE")

class SongList:
    def __init__(self, songs=None):
        self.songs = list(songs) if songs is not None else []

    def add(self, song):
        self.songs.append(song)

    def __len__(self):
        return len(self.songs)

    def __getitem__(self, index):
        if isinstance(index, slice):
            return SongList(self.songs[index])
        return self.songs[index]

    def __repr__(self):
        return f"SongList({self.songs})"


