import math


class Frac:
    def __init__(self, num, den):
        if den == 0:
            raise ZeroDivisionError("zero denominator")
        g = math.gcd(num, den)
        num //= g
        den //= g
        if den < 0:                 # keep the sign in the numerator
            num, den = -num, -den
        self.num = num
        self.den = den

    def __add__(self, other):
        return Frac(self.num * other.den + other.num * self.den, self.den * other.den)

    def __sub__(self, other):
        return Frac(self.num * other.den - other.num * self.den, self.den * other.den)

    def __mul__(self, other):
        return Frac(self.num * other.num, self.den * other.den)

    def __str__(self):
        if self.den == 1:
            return str(self.num)
        return f"{self.num}/{self.den}"


q = int(input())
for _ in range(q):
    left, op, right = input().split()
    try:
        a = Frac(*map(int, left.split("/")))
        b = Frac(*map(int, right.split("/")))
        if op == "+":
            print(a + b)
        elif op == "-":
            print(a - b)
        else:
            print(a * b)
    except ZeroDivisionError as e:
        print(f"ERROR: {e}")

class Base:
    def hello(self):
        return "Base"


class Left(Base):
    def hello(self):
        return "Left -> " + super().hello()


class Right(Base):
    def hello(self):
        return "Right -> " + super().hello()


class Child(Left, Right):
    def hello(self):
        return "Child -> " + super().hello()


class Child2(Right, Left):
    def hello(self):
        return "Child2 -> " + super().hello()


classes = {c.__name__: c for c in (Base, Left, Right, Child, Child2)}

q = int(input())
for _ in range(q):
    command, name = input().split()
    if name not in classes:
        print("UNKNOWN CLASS")
        continue
    cls = classes[name]
    if command == "MRO":
        print(" -> ".join(c.__name__ for c in cls.__mro__))
    elif command == "CALL":
        print(cls().hello())

class Product:
    def __init__(self, name, price):
        self._name = name
        self.price = price          # goes through the setter

    @property
    def name(self):
        return self._name

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        if value < 0:
            raise ValueError("price cannot be negative")
        self._price = value

    def apply_discount(self, pct):
        if pct < 0 or pct > 100:
            raise ValueError("discount must be 0-100")
        self.price = self.price * (1 - pct / 100)


name, start = input().split()
q = int(input())

try:
    product = Product(name, float(start))
except ValueError as e:
    print(f"ERROR: {e}")
else:
    for _ in range(q):
        parts = input().split()
        command = parts[0]
        if command == "GET":
            print(f"{product.name}: {product.price:.2f}")
            continue
        try:
            if command == "SET":
                product.price = float(parts[1])
            elif command == "DISCOUNT":
                product.apply_discount(float(parts[1]))
            elif command == "RENAME":
                product.name = parts[1]
            print("OK")
        except ValueError as e:
            print(f"ERROR: {e}")
        except AttributeError:
            print("ERROR: read-only")

class InvalidTransition(Exception):
    pass


class State:
    name = "STATE"

    def _refuse(self, action):
        raise InvalidTransition(f"cannot {action} when {self.name}")

    def pay(self):
        self._refuse("pay")

    def ship(self):
        self._refuse("ship")

    def deliver(self):
        self._refuse("deliver")

    def cancel(self):
        self._refuse("cancel")


class Draft(State):
    name = "DRAFT"

    def pay(self):
        return Paid()

    def cancel(self):
        return Cancelled()


class Paid(State):
    name = "PAID"

    def ship(self):
        return Shipped()

    def cancel(self):
        return Cancelled()


class Shipped(State):
    name = "SHIPPED"

    def deliver(self):
        return Delivered()


class Delivered(State):
    name = "DELIVERED"


class Cancelled(State):
    name = "CANCELLED"


class Order:
    def __init__(self):
        self.state = Draft()

    def do(self, action):
        self.state = getattr(self.state, action)()
        return self.state.name


order = Order()

