    command = input().strip()
    if command == "STATUS":
        print(order.state.name)
        continue
    try:
        print(order.do(command.lower()))
    except InvalidTransition as e:
        print(f"INVALID: {e}")

class Resource:
    open_count = 0

    def __init__(self, name):
        self.name = name

    def __enter__(self):
        Resource.open_count += 1
        print(f"acquire {self.name}")
        return self

    def __exit__(self, exc_type, exc, tb):
        Resource.open_count -= 1
        print(f"release {self.name}")
        if exc_type is not None and issubclass(exc_type, ValueError):
            print(f"suppressed ValueError: {exc}")
            return True             # swallow the error
        return False                # let anything else continue


q = int(input())
for _ in range(q):
    parts = input().split()
    if parts[0] == "OPEN":
        print(Resource.open_count)
        continue
    name, action = parts[1], parts[2]
    try:
        with Resource(name):
            if action == "OK":
                print(f"working {name}")
            elif action == "VALUE":
                raise ValueError("bad value")
            elif action == "KEY":
                raise KeyError("missing")
    except Exception as e:
        print(f"unhandled {type(e).__name__}")

class Document:
    def __init__(self):
        self.text = ""


class AppendCommand:
    def __init__(self, doc, text):
        self.doc = doc
        self.text = text

    def execute(self):
        self.doc.text += self.text

    def undo(self):
        self.doc.text = self.doc.text[:len(self.doc.text) - len(self.text)]


class DeleteCommand:
    def __init__(self, doc, n):
        self.doc = doc
        self.n = n
        self.removed = ""

    def execute(self):
        k = min(self.n, len(self.doc.text))
        cut = len(self.doc.text) - k
        self.removed = self.doc.text[cut:]      # remember it for undo
        self.doc.text = self.doc.text[:cut]

    def undo(self):
        self.doc.text += self.removed


class Editor:
    def __init__(self, doc):
        self.doc = doc
        self.undo_stack = []
        self.redo_stack = []

    def run(self, command):
        command.execute()
        self.undo_stack.append(command)
        self.redo_stack.clear()             # a new change ends the redo history

    def undo(self):
        if not self.undo_stack:
            return False
        command = self.undo_stack.pop()
        command.undo()
        self.redo_stack.append(command)
        return True

    def redo(self):
        if not self.redo_stack:
            return False
        command = self.redo_stack.pop()
        command.execute()
        self.undo_stack.append(command)
        return True


doc = Document()
editor = Editor(doc)

q = int(input())
for _ in range(q):
    line = input()
    if line.startswith("APPEND "):
        editor.run(AppendCommand(doc, line[7:]))
    elif line.startswith("DELETE "):
        editor.run(DeleteCommand(doc, int(line[7:])))
    elif line == "UNDO":
        if not editor.undo():
            print("NOTHING TO UNDO")
    elif line == "REDO":
        if not editor.redo():
            print("NOTHING TO REDO")
    elif line == "SHOW":
        print(f"[{doc.text}]")

class Date:
    def __init__(self, year, month, day):
        self.year = year
        self.month = month
        self.day = day

    @staticmethod
    def is_leap(year):
        return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0

    @staticmethod
    def is_valid(year, month, day):
        if month < 1 or month > 12 or year < 1:
            return False
        lengths = [31, 29 if Date.is_leap(year) else 28, 31, 30, 31, 30,
                   31, 31, 30, 31, 30, 31]
        return 1 <= day <= lengths[month - 1]

    @classmethod
    def from_string(cls, text):
        parts = text.split("-")
        if len(parts) != 3 or not all(p.isdigit() for p in parts):
            raise ValueError("invalid date")
        year, month, day = (int(p) for p in parts)
        if not cls.is_valid(year, month, day):
            raise ValueError("invalid date")
        return cls(year, month, day)        # cls is Date or EuroDate

    def __str__(self):
        return f"{self.year:04d}-{self.month:02d}-{self.day:02d}"


class EuroDate(Date):
    def __str__(self):
        return f"{self.day:02d}/{self.month:02d}/{self.year:04d}"


q = int(input())
for _ in range(q):
    command, value = input().split()
    try:
        if command == "PARSE":
            print(Date.from_string(value))
        elif command == "PARSE_EU":
            d = EuroDate.from_string(value)
            print(f"{d} ({type(d).__name__})")
        elif command == "LEAP":
            print(Date.is_leap(int(value)))
    except ValueError:
        print("INVALID DATE")

from functools import total_ordering


@total_ordering
class Version:
    def __init__(self, text):
        self.text = text
        parts = [int(p) for p in text.split(".")]
        while len(parts) > 1 and parts[-1] == 0:
            parts.pop()                 # 1.0.0 is the same as 1
        self.key = tuple(parts)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.key == other.key

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.key < other.key

    def __hash__(self):
        return hash(self.key)

    def __repr__(self):
        return self.text


q = int(input())
for _ in range(q):
    parts = input().split()
    command = parts[0]
    versions = [Version(t) for t in parts[1:]]
    if command == "CMP":
        a, b = versions
        print(a < b, a == b, a > b, a <= b)
    elif command == "SORT":
        print(" ".join(repr(v) for v in sorted(versions)))
    elif command == "MAX":
        print(repr(max(versions)))
    elif command == "UNIQUE":
        print(len(set(versions)))

import json


class JsonMixin:
    def to_json(self):
        return json.dumps(vars(self), sort_keys=True)


class EqualityMixin:
    def __eq__(self, other):
        if type(self) is not type(other):
            return NotImplemented
        return vars(self) == vars(other)


class User(JsonMixin, EqualityMixin):
    def __init__(self, name, email):
        self.name = name
        self.email = email


class Product(JsonMixin):
    def __init__(self, title, price):
        self.title = title
        self.price = price


objects = []

q = int(input())
for _ in range(q):
    parts = input().split()
    command = parts[0]
    if command == "USER":
        objects.append(User(parts[1], parts[2]))
    elif command == "PRODUCT":
        objects.append(Product(parts[1], int(parts[2])))
    elif command == "JSON":
        print(objects[int(parts[1])].to_json())
    elif command == "SAME":
        print(objects[int(parts[1])] == objects[int(parts[2])])
    elif command == "MIXINS":
        obj = objects[int(parts[1])]
        found = [m.__name__ for m in (JsonMixin, EqualityMixin) if isinstance(obj, m)]
        print(f"{type(obj).__name__}: {', '.join(found)}")

from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = OrderedDict()       # oldest first
        self.last_evicted = None

    def __setitem__(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)
        self.last_evicted = None
        if len(self.data) > self.capacity:
            old_key, _ = self.data.popitem(last=False)
            self.last_evicted = old_key

    def __getitem__(self, key):
        value = self.data[key]          # KeyError if missing
        self.data.move_to_end(key)
        return value

    def __delitem__(self, key):
        del self.data[key]

    def __contains__(self, key):
        return key in self.data         # does not change the order

    def __len__(self):
        return len(self.data)

    def __repr__(self):
        return f"LRUCache({list(self.data)})"


cache = LRUCache(int(input()))

q = int(input())
for _ in range(q):
    parts = input().split()
    command = parts[0]
    if command == "PUT":
        cache[parts[1]] = parts[2]
        if cache.last_evicted is None:
            print("OK")
        else:
            print(f"OK (evicted {cache.last_evicted})")
    elif command == "GET":
        try:
            print(cache[parts[1]])
        except KeyError:
            print("MISS")
    elif command == "HAS":
        print(parts[1] in cache)
    elif command == "DEL":
        try:
            del cache[parts[1]]
            print("OK")
        except KeyError:
            print("MISS")
    elif command == "LEN":
        print(len(cache))
    elif command == "SHOW":
        print(repr(cache))
